:host(.chapter-container) {
  --ink: #2D3748;
  --muted: #718096;
  --accent: #2C5282;
  --paper: #F7FAFC;
  --line: #E2E8F0;
  --warm: #EBF8FF;

  display: block;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
  max-width: 900px;
  margin: 0 auto;
}

.chapter-header h1 {
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 0.5rem;
  letter-spacing: -0.02em;
}

.lead-text {
  font-size: 1.125rem;
  color: var(--muted);
  max-width: 700px;
  margin-bottom: 2.5rem;
}

.interaction-workspace {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 2rem;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1.5rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}

@media (max-width: 768px) {
  .interaction-workspace {
    grid-template-columns: 1fr;
  }
}

.control-panel h3 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  margin-bottom: 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.badge {
  font-size: 0.75rem;
  background: var(--warm);
  color: var(--accent);
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-weight: 600;
}

.condition-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.condition-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--line);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  background: #fff;
  font-size: 0.95rem;
  color: var(--ink);
}

.condition-item:hover, .condition-item:focus {
  border-color: var(--accent);
  background: var(--warm);
  outline: none;
  box-shadow: 0 2px 4px rgba(44, 82, 130, 0.1);
}

.condition-item[aria-selected="true"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.condition-item .icon {
  font-size: 1.25rem;
}

.evidence-display {
  position: relative;
  min-height: 300px;
}

.display-card {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, transform 0.3s ease;
  transform: translateY(10px);
  background: #fff;
  padding: 1rem;
  border-radius: 6px;
  border: 1px solid var(--line);
  display: flex;
  flex-direction: column;
}

.display-card.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  position: relative;
  height: auto;
  min-height: auto;
}

.display-card h4 {
  font-size: 1.25rem;
  color: var(--accent);
  margin-top: 0;
  margin-bottom: 0.75rem;
  border-bottom: 2px solid var(--warm);
  padding-bottom: 0.5rem;
}

.claim-text {
  font-size: 1rem;
  color: var(--ink);
  margin-bottom: 1.5rem;
  font-weight: 500;
}

.evidence-block {
  background: var(--paper);
  padding: 1.25rem;
  border-radius: 6px;
  border-left: 4px solid var(--accent);
  flex-grow: 1;
}

blockquote {
  margin: 0 0 1rem 0;
  font-style: italic;
  color: var(--ink);
  font-size: 0.95rem;
  line-height: 1.7;
}

.source-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.btn-source {
  background: #fff;
  border: 1px solid var(--line);
  color: var(--muted);
  padding: 0.4rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-source:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--warm);
}

.chapter-footer {
  margin-top: 2.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
}

.takeaway {
  font-size: 0.95rem;
  color: var(--muted);
  background: #fff;
  padding: 1rem;
  border-radius: 6px;
  border: 1px dashed var(--line);
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}

