(function() {
  const container = document.currentScript.closest('.chapter-container');
  const items = container.querySelectorAll('.condition-item');
  const cards = container.querySelectorAll('.display-card');

  function activateCard(targetId) {
    // Deactivate all
    items.forEach(i => {
      i.setAttribute('aria-selected', 'false');
      i.removeAttribute('tabindex');
    });
    cards.forEach(c => c.classList.remove('active'));

    // Activate target
    const targetItem = container.querySelector(`.condition-item[data-target="${targetId}"]`);
    const targetCard = container.querySelector(`#${targetId}`);

    if (targetItem && targetCard) {
      targetItem.setAttribute('aria-selected', 'true');
      targetItem.setAttribute('tabindex', '0');
      targetCard.classList.add('active');

      // Scroll into view on mobile if needed
      if (window.innerWidth < 768) {
        targetCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
  }

  // Initialize first item
  if (items.length > 0) {
    activateCard(items[0].dataset.target);
  }

  // Event Listeners
  items.forEach(item => {
    item.addEventListener('click', () => {
      activateCard(item.dataset.target);
    });

    item.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        activateCard(item.dataset.target);
      }
    });
  });

  // Source Button Handling (Delegated to Kernel)
  container.addEventListener('click', (e) => {
    if (e.target.matches('.btn-source')) {
      // The kernel handles the data-source attribute
      // No action needed here other than ensuring event bubbles if necessary
      // But per spec, kernel handles bridge. We just ensure no default link behavior.
      e.preventDefault(); 
    }
  });
})();
